package com.lexiscan.document; import com.lexiscan.common.ApiException; import com.lexiscan.config.AppProperties; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import org.springframework.web.multipart.MultipartFile; import java.io.*; import java.nio.file.*; import java.util.*;
@Service public class FileStorage { final Path root; public FileStorage(AppProperties p)throws IOException{root=Paths.get(p.storageDir()).toAbsolutePath().normalize();Files.createDirectories(root);} public record Stored(String path,String type,String safeName,long size){} public Stored save(MultipartFile f)throws IOException{if(f.isEmpty()||f.getSize()>10*1024*1024)throw new ApiException(HttpStatus.BAD_REQUEST,"File must be non-empty and at most 10 MB");var name=Optional.ofNullable(f.getOriginalFilename()).orElse("document").replaceAll("[^a-zA-Z0-9._ -]","_");var lower=name.toLowerCase();String type;if(lower.endsWith(".pdf")&&magic(f,new byte[]{0x25,0x50,0x44,0x46}))type="PDF";else if(lower.endsWith(".docx")&&magic(f,new byte[]{0x50,0x4b,0x03,0x04}))type="DOCX";else throw new ApiException(HttpStatus.BAD_REQUEST,"Only genuine PDF and DOCX files are allowed");var path=root.resolve(UUID.randomUUID()+"."+(type.equals("PDF")?"pdf":"docx"));try(var in=f.getInputStream()){Files.copy(in,path,StandardCopyOption.REPLACE_EXISTING);}return new Stored(path.toString(),type,name,f.getSize());} private boolean magic(MultipartFile f,byte[] expected)throws IOException{try(var in=f.getInputStream()){for(byte b:expected)if(in.read()!=(b&255))return false;return true;}} public void delete(String path){try{Files.deleteIfExists(Paths.get(path));}catch(IOException ignored){}}}
